}

{
  "minimumBrightnessLevel": 20,   // integer 0-100 | 0 = off, 100 = maximum
  "maximumBrightnessLevel": 100    // must be >= minimumBrightnessLevel
}

{
  "hour": 2   // 24h clock integer 0-23 — reboot fires at a random minute within this hour
              // staggers fleet reboots to avoid simultaneous restarts
              // Production devices only — no effect on staging/dev
}

{
  "force": false   // false = check for active transaction before rebooting (recommended)
               // true  = reboot immediately — can interrupt an active transaction
}

